// DeepCopyInto is a deepcopy function, copying the receiver, writing into out. in must be non-nil.
func (in *HostAllocation) DeepCopyInto(out *HostAllocation) {
	*out = *in
}

// DeepCopy is a deepcopy function, copying the receiver, creating a new HostAllocation.
func (in *HostAllocation) DeepCopy() *HostAllocation {
	if in == nil {
		return nil
	}
	out := new(HostAllocation)
	in.DeepCopyInto(out)
	return out
}

// DeepCopyInto is a deepcopy function, copying the receiver, writing into out. in must be non-nil.
func (in *PreprovisionedHost) DeepCopyInto(out *PreprovisionedHost) {
	*out = *in
	if in.Addresses != nil {
		out.Addresses = make([]clusterv1.MachineAddress, len(in.Addresses))
		copy(out.Addresses, in.Addresses)
	}
	if in.Labels != nil {
		out.Labels = make(map[string]string, len(in.Labels))
		for key, val := range in.Labels {
			out.Labels[key] = val
		}
	}
}

// DeepCopy is a deepcopy function, copying the receiver, creating a new PreprovisionedHost.
func (in *PreprovisionedHost) DeepCopy() *PreprovisionedHost {
	if in == nil {
		return nil
	}
	out := new(PreprovisionedHost)
	in.DeepCopyInto(out)
	return out
}

